namespace {
using namespace dbms;
struct Row {int id=0;int64_t rid=0;std::vector<std::string> cells;std::vector<bool> nulls;};
void require(bool good,const char* detail){if(!good)throw std::runtime_error(detail);}
int64_t clockNs(clockid_t id){timespec t{};require(::clock_gettime(id,&t)==0,"actual clock unavailable");return int64_t(t.tv_sec)*1000000000+t.tv_nsec;}
std::string hex(const std::string& value){const char* digits="0123456789abcdef";std::string out;for(unsigned char c:value){out+=digits[c>>4];out+=digits[c&15];}return out;}
std::vector<Row> snapshot(StorageEngine& engine,const std::string& table) {
    const auto schema=engine.getTableSchema("info",table);require(schema.len>0,"actual schema missing");
    TableScanOp scan(&engine,"info",table);require(scan.open(),"actual TableScan open");
    std::string raw;std::vector<Row> rows;std::set<int64_t> unique;
    while(scan.next(raw)) {
        const auto origin=scan.scanOrigin();const auto rid=scan.lastRid();
        require(origin.engine==&engine && origin.dbname=="info" && origin.tablename==table && origin.rid==rid && rid>0 && unique.insert(rid).second,"actual scan ownership/RID");
        std::vector<bool> bitmap;require(scan.lastStoredNullBitmap(bitmap)&&bitmap.size()==schema.len,"real full physical NULL bitmap");
        Row row;row.rid=rid;
        for(size_t col=0;col<schema.len;++col) {
            const bool null=scan.lastColumnIsNull(col);require(null==bitmap[col],"NULL accessors disagree");row.nulls.push_back(null);
            row.cells.push_back(null?std::string{}:StorageEngine::extractColumnValueStatic(raw,schema,col));
        }
        require(!row.nulls[0],"actual PK NULL");size_t used=0;row.id=std::stoi(row.cells[0],&used);require(used==row.cells[0].size(),"actual PK parse");rows.push_back(std::move(row));
    }
    require(!scan.hasError(),"actual TableScan error");scan.close();
    std::sort(rows.begin(),rows.end(),[](const Row&a,const Row&b){return a.id<b.id;});return rows;
}
void checkPrimary(const std::vector<Row>& rows,bool sentinel=false) {
    require(rows.size()==1000+size_t(sentinel),"all1000 actual fixture rows plus optional real mutation sentinel");
    for(size_t i=0;i<1000;++i) {
        const auto& row=rows[i];const int id=int(i+1);
        require(row.id==id && row.nulls==std::vector<bool>(4,false) && row.cells==std::vector<std::string>{std::to_string(id),std::to_string(id%100),std::to_string(id%1000),"row-"+std::to_string(id)},"independent complete fixture values/NULLs");
    }
    if(sentinel)require(rows.back().id==2001 && rows.back().cells==std::vector<std::string>{"2001","1","1","restore-sentinel"},"actual pre-restore sentinel must exist");
}
