void outputRestoreDiagnostic(const std::vector<Row>& visible) {
    const auto high=TxnIdGenerator::instance().maxCommittedTxId();
    auto bytes=[](const std::filesystem::path& path) {
        std::ifstream f(path,std::ios::binary);require(bool(f),"diagnostic existing file open");
        return std::string(std::istreambuf_iterator<char>(f),std::istreambuf_iterator<char>());
    };
    std::cout<<"RESTORE_HORIZON_DIAGNOSTIC visible_probe_count="<<visible.size()
             <<" allocation_highwater="<<high<<" autocommit_low_limit="<<(high+1)
             <<" txnid_hex="<<hex(bytes(".txnid"))
             <<" physical_relation_ids_hex="<<hex(bytes(".physical_relation_ids"))<<'\n';
    const auto data=bytes("info/backup_null_probe.dt");
    require(data.size()>=sizeof(DataFileHeader),"diagnostic existing heap header");
    DataFileHeader header{};std::memcpy(&header,data.data(),sizeof(header));
    require(header.magic==DATA_FILE_MAGIC&&header.formatVersion==DATA_FILE_FORMAT_VERSION&&
            header.headerChecksum==computeDataFileHeaderChecksum(header)&&
            data.size()==size_t(header.numPages)*PgPage::PAGE_SIZE,"diagnostic real heap format/extent");
    CommitLog clog("info");size_t physical=0;
    for(uint32_t block=1;block<header.numPages;++block) {
        std::vector<char> pageBytes(data.begin()+size_t(block)*PgPage::PAGE_SIZE,
                                    data.begin()+size_t(block+1)*PgPage::PAGE_SIZE);
        PgPage page(pageBytes.data());require(page.isValid(block),"diagnostic real page validity");
        page.forEachLive([&](OffsetNumber line,const char* tuple,size_t len) {
            require(len>=sizeof(HeapTupleHeaderData),"diagnostic actual tuple header");
            const auto* t=castHeapHeader(tuple);++physical;
            std::cout<<"RESTORE_HORIZON_PHYSICAL_TUPLE rid="<<StorageEngine::encodeRid(block,line-1)
                     <<" xmin="<<t->t_fields.t_xmin<<" xmax="<<t->t_fields.t_xmax
                     <<" command_id="<<t->t_fields.t_cid<<" bytes="<<len
                     <<" clog="<<CommitLog::statusName(clog.getStatus(t->t_fields.t_xmin))<<'\n';
        });
    }
    std::cout<<"RESTORE_HORIZON_PHYSICAL_COUNT count="<<physical<<'\n';
    output("diagnostic-restored","backup_null_probe",visible);std::cout.flush();
}

