+bool WALManager::readSnapshotTransactionHighWater(
+    const std::filesystem::path& walDir, uint64_t& highWater) {
+    try {
+        // The constructor only selects this path's in-process mutex. Do not use
+        // ensureOpen(): opening a snapshot must never create persistent state.
+        WALManager wal(walDir);
+        wal.directoryFd_ = ::open(walDir.c_str(),
+            O_RDONLY | O_DIRECTORY | O_CLOEXEC | O_NOFOLLOW);
+        if (wal.directoryFd_ < 0 || !wal.refersToCurrentDirectory() ||
+            !wal.loadTimeline()) return false;
+
+        std::map<uint32_t, std::map<uint32_t, uintmax_t>> timelines;
+        for (const auto& entry : std::filesystem::directory_iterator(walDir)) {
+            const std::string name = entry.path().filename().string();
+            if (name.size() != 24 || !std::all_of(name.begin(), name.end(),
+                    [](unsigned char ch) {
+                        return (ch >= '0' && ch <= '9') ||
+                               (ch >= 'a' && ch <= 'f') ||
+                               (ch >= 'A' && ch <= 'F');
+                    })) continue;
+            const auto timeline = static_cast<uint32_t>(
+                std::stoull(name.substr(0, 8), nullptr, 16));
+            uint32_t segment = 0;
+            if (timeline == 0 || !parseSegmentName(name, timeline, segment))
+                return false;
+            if (!entry.is_regular_file() || entry.is_symlink()) return false;
+            const uintmax_t size = entry.file_size();
+            if (size > kSegmentSize ||
+                !timelines[timeline].emplace(segment, size).second) return false;
+        }
+
+        uint64_t result = 0;
+        for (const auto& [timeline, segments] : timelines) {
+            // Each retained chain may omit a prefix, never an interior segment.
+            auto prior = segments.begin();
+            for (auto current = std::next(prior); current != segments.end();
+                 ++current, ++prior) {
+                if (prior->first == std::numeric_limits<uint32_t>::max() ||
+                    current->first != prior->first + 1 ||
+                    prior->second != kSegmentSize) return false;
+            }
+            wal.timelineId_ = timeline;
+            if (!wal.refreshCurrentLsnFromDisk()) return false;
+            wal.open_ = true;
+            const Lsn limit = wal.currentWriteLsn();
+            const Lsn boundary = static_cast<Lsn>(segments.begin()->first) * kSegmentSize;
+            Lsn lsn = boundary;
+            if (boundary != 0) {
+                const auto retained = retainedRecordStart(
+                    wal, walDir.parent_path() / "checkpoint", boundary, limit);
+                if (retained) lsn = *retained;
+                // No anchor does not permit guessing a header in payload.
+                // The boundary can still be a checked all-zero switch suffix.
+            }
+            std::optional<Lsn> previous;
+            while (lsn < limit) {
+                const auto record = wal.ReadRecord(lsn);
+                if (!record) {
+                    // switchWal pads to a segment boundary. Check the ENTIRE
+                    // remaining suffix, then continue into later segments.
+                    const Lsn end = std::min(limit,
+                        (lsn / kSegmentSize + 1) * kSegmentSize);
+                    std::array<char, 65536> zeros{};
+                    for (Lsn offset = lsn; offset < end;) {
+                        const size_t count = static_cast<size_t>(
+                            std::min<Lsn>(zeros.size(), end - offset));
+                        if (!wal.readBytes(offset, zeros.data(), count) ||
+                            std::any_of(zeros.begin(), zeros.begin() + count,
+                                [](char byte) { return byte != 0; })) return false;
+                        offset += count;
+                    }
+                    lsn = end;
+                    continue;
+                }
+                if (previous) {
+                    if (record->header.xl_prev != *previous) return false;
+                } else if ((lsn == 0 && record->header.xl_prev != 0) ||
+                           (lsn != 0 && record->header.xl_prev >= lsn)) {
+                    return false;
+                }
+                result = std::max(result, record->header.xl_xid);
+                if (record->rmid() == RM_CHECKPOINT_ID) {
+                    if (record->data.size() < sizeof(uint64_t)) return false;
+                    uint64_t nextXid = 0;
+                    std::memcpy(&nextXid, record->data.data(), sizeof(nextXid));
+                    if (nextXid == 0) return false;
+                    result = std::max(result, nextXid - 1);
+                }
+                previous = lsn;
+                const Lsn next = lsn + record->header.xl_tot_len;
+                if (next <= lsn || next > limit) return false;
+                lsn = next;
+            }
+        }
+        if (!wal.refersToCurrentDirectory()) return false;
+        highWater = result;
+        return true;
+    } catch (...) {
+        return false;
+    }
