// OFF-TREE same-source public restore timing; no allocator/profiler hooks. Runtime requires Root quiet release.
#include "catalog/type_registry.h"
#include "commands/TableManage.h"
#include "executor/ExecutionPlan.h"
#include <algorithm>
#include <chrono>
#include <cstdlib>
#include <ctime>
#include <filesystem>
#include <iostream>
#include <map>
#include <optional>
#include <set>
#include <stdexcept>
#include <string>
#include <vector>

namespace {
using namespace dbms;
struct Row {int id=0;int64_t rid=0;std::vector<std::string> cells;std::vector<bool> nulls;};
void require(bool good,const char* detail){if(!good)throw std::runtime_error(detail);}
int64_t clockNs(clockid_t id){timespec t{};require(::clock_gettime(id,&t)==0,"actual clock unavailable");return int64_t(t.tv_sec)*1000000000+t.tv_nsec;}
std::string hex(const std::string& value){const char* digits="0123456789abcdef";std::string out;for(unsigned char c:value){out+=digits[c>>4];out+=digits[c&15];}return out;}
std::vector<Row> snapshot(StorageEngine& engine,const std::string& table) {
    const auto schema=engine.getTableSchema("info",table);require(schema.len>0,"actual schema missing");
    TableScanOp scan(&engine,"info",table);require(scan.open(),"actual TableScan open");
    std::string raw;std::vector<Row> rows;std::set<int64_t> unique;
    while(scan.next(raw)) {
        const auto origin=scan.scanOrigin();const auto rid=scan.lastRid();
        require(origin.engine==&engine && origin.dbname=="info" && origin.tablename==table && origin.rid==rid && rid>0 && unique.insert(rid).second,"actual scan ownership/RID");
        std::vector<bool> bitmap;require(scan.lastStoredNullBitmap(bitmap)&&bitmap.size()==schema.len,"real full physical NULL bitmap");
        Row row;row.rid=rid;
        for(size_t col=0;col<schema.len;++col) {
            const bool null=scan.lastColumnIsNull(col);require(null==bitmap[col],"NULL accessors disagree");row.nulls.push_back(null);
            row.cells.push_back(null?std::string{}:StorageEngine::extractColumnValueStatic(raw,schema,col));
        }
        require(!row.nulls[0],"actual PK NULL");size_t used=0;row.id=std::stoi(row.cells[0],&used);require(used==row.cells[0].size(),"actual PK parse");rows.push_back(std::move(row));
    }
    require(!scan.hasError(),"actual TableScan error");scan.close();
    std::sort(rows.begin(),rows.end(),[](const Row&a,const Row&b){return a.id<b.id;});return rows;
}
void checkPrimary(const std::vector<Row>& rows,bool sentinel=false) {
    require(rows.size()==1000+size_t(sentinel),"all1000 actual fixture rows plus optional real mutation sentinel");
    for(size_t i=0;i<1000;++i) {
        const auto& row=rows[i];const int id=int(i+1);
        require(row.id==id && row.nulls==std::vector<bool>(4,false) && row.cells==std::vector<std::string>{std::to_string(id),std::to_string(id%100),std::to_string(id%1000),"row-"+std::to_string(id)},"independent complete fixture values/NULLs");
    }
    if(sentinel)require(rows.back().id==2001 && rows.back().cells==std::vector<std::string>{"2001","1","1","restore-sentinel"},"actual pre-restore sentinel must exist");
}
bool same(const std::vector<Row>& a,const std::vector<Row>& b) {
    if(a.size()!=b.size())return false;
    for(size_t i=0;i<a.size();++i)if(a[i].id!=b[i].id || a[i].rid!=b[i].rid || a[i].nulls!=b[i].nulls || a[i].cells!=b[i].cells)return false;
    return true;
}
void output(const std::string& phase,const std::string& table,const std::vector<Row>& rows) {
    for(const auto& row:rows) {
        std::cout<<"PUBLIC_BACKUP_API_ROW phase="<<phase<<" table="<<table<<" id="<<row.id<<" rid="<<row.rid<<" nulls=";
        for(bool null:row.nulls)std::cout<<char(null?'1':'0');std::cout<<" cells_hex=";
        for(size_t i=0;i<row.cells.size();++i){if(i)std::cout<<',';std::cout<<hex(row.cells[i]);}std::cout<<'\n';
    }
}
void createNullProbe(StorageEngine& engine) {
    require(!engine.tableExists("info","backup_null_probe"),"fresh owned NULL probe name");
    TableSchema schema;schema.tablename="backup_null_probe";schema.formatVersion=DATA_FILE_FORMAT_VERSION;
    schema.append(makeIntColumn("id",false,4,true));schema.append(makeIntColumn("n",true,4));schema.append(makeTextColumn("t",true));
    require(engine.createTable("info",schema)==DBStatus::OK,"actual NULL probe table");
    const std::vector<StorageEngine::SqlRow> inputs={
        {{"id","1"},{"n",std::nullopt},{"t",std::nullopt}},
        {{"id","2"},{"n","0"},{"t",""}},
        {{"id","3"},{"n","-2147483648"},{"t","NULL"}},
        {{"id","4"},{"n","2147483647"},{"t",std::string(6000,'T')+"λ"}}};
    for(const auto& row:inputs)require(engine.insertRow("info","backup_null_probe",row)==DBStatus::OK,"actual NULL/empty/literalNULL/TOAST input");
}
void checkNullProbe(const std::vector<Row>& rows) {
    require(rows.size()==4,"actual probe count");
    const std::vector<std::vector<std::optional<std::string>>> expected={
        {{"1"},{},{}},{{"2"},{"0"},{""}},{{"3"},{"-2147483648"},{"NULL"}},{{"4"},{"2147483647"},{std::string(6000,'T')+"λ"}}};
    for(size_t i=0;i<4;++i){require(rows[i].id==int(i+1)&&rows[i].cells.size()==3,"actual probe widths/ids");
        for(size_t c=0;c<3;++c)require(rows[i].nulls[c]==!expected[i][c] && (!expected[i][c]||rows[i].cells[c]==*expected[i][c]),"independent probe full values/NULLs");}
}
}
int main(int argc,char** argv) {
    try {
        require(argc==4,"operation seed-null/create-check/create-timed/restore-check, owned image path, withNULLprobe0/1 required");
        const std::string operation=argv[1];const bool seed=operation=="seed-null",create=operation=="create-check"||operation=="create-timed",restoreTimed=operation=="restore-timed",timed=operation=="create-timed"||restoreTimed;
        require(seed||create||operation=="restore-check"||restoreTimed,"fixed public operation required");
        const bool nullProbe=std::string(argv[3])=="1";require(nullProbe||std::string(argv[3])=="0","fixed NULL probe flag");
        require(operation!="create-timed"||!nullProbe,"create performance fixture remains original closed1000 rows");
        require(!restoreTimed||nullProbe,"restore timing requires real original4-row NULL/TOAST probe");
        const auto cwd=std::filesystem::canonical(std::filesystem::current_path());
        const char* data=std::getenv("DBMS_DATA_DIR"),*owned=std::getenv("DBMS_BACKUP_EXPERIMENT_ROOT");
        require(data&&owned&&std::filesystem::equivalent(cwd,data),"explicit real owned cluster");
        const auto experiment=std::filesystem::canonical(owned),image=std::filesystem::absolute(argv[2]).lexically_normal();
