    explicit ForeignHold(bool paused){thread=std::thread([this,paused]{try{check(g_engine.setIsolationLevel(IsolationLevel::REPEATABLE_READ),"actual foreign isolation");watchShared=paused;pauseAfterXid=paused;check(g_engine.beginTransaction(FOREIGN)==DBStatus::OK,"real foreign BEGIN");pauseAfterXid=false;watchShared=false;xid=g_engine.currentTxnId();exportBefore=g_engine.exportSnapshot();check(!exportBefore.empty(),"real foreign exported repeatable snapshot");rowsBefore=foreignRows();const auto* view=g_engine.getCurrentReadView();check(view!=nullptr,"actual foreign view");before=*view;{std::lock_guard<std::mutex> l(mutex);ready=true;cv.notify_all();}std::unique_lock<std::mutex> l(mutex);cv.wait(l,[this]{return release;});l.unlock();exportAfter=g_engine.exportSnapshot();after=*g_engine.getCurrentReadView();rowsAfter=foreignRows();check(g_engine.commitTransaction()==DBStatus::OK,"real foreign terminal COMMIT");}catch(...){error=std::current_exception();if(g_engine.inTransaction())(void)g_engine.rollbackTransaction();{std::lock_guard<std::mutex> l(mutex);ready=true;cv.notify_all();}}});}
    bool waitReady(){std::unique_lock<std::mutex> l(mutex);return cv.wait_for(l,std::chrono::seconds(10),[this]{return ready;});}
    void finish(){releaseGap();{std::lock_guard<std::mutex> l(mutex);release=true;cv.notify_all();}if(thread.joinable())thread.join();}
    void verify(){if(error)std::rethrow_exception(error);check(xid>0&&sameView(before,after)&&exportBefore==exportAfter,"actual foreign read view and exported bytes never rewritten");check(sameRows(rowsBefore,rowsAfter),"all actual foreign values/RIDs/NULL unchanged");}
    ~ForeignHold(){finish();}
};
void seedForeign(){check(g_engine.createDatabase(FOREIGN,"utf8")==DBStatus::OK,"real independent foreign database");TableSchema t;t.tablename="f";t.formatVersion=DATA_FILE_FORMAT_VERSION;t.append(makeIntColumn("id",false,4,true));t.append(makeIntColumn("n",true,4));t.append(makeTextColumn("t",true));check(g_engine.createTable(FOREIGN,t)==DBStatus::OK,"real foreign physical table");check(g_engine.insertRow(FOREIGN,"f",{{"id","1"},{"n","101"},{"t","foreign-stable"}})==DBStatus::OK,"foreign seed1");check(g_engine.insertRow(FOREIGN,"f",{{"id","2"},{"n",std::nullopt},{"t",""}})==DBStatus::OK,"foreign NULL/empty seed2");}
void verifyUnchangedTarget(const std::vector<Row>& before,uint64_t identity){const auto now=snapshot("base");expectedCells(now,earlyValues());check(sameRows(now,before),"rejected restore preserves full target values/RIDs/NULL");check(!g_engine.tableExists(DB,"added")&&g_engine.getTableSchema(DB,"base").physicalRelationId==identity,"rejected restore publishes no new target schema/generation");}
void concurrentWorker(const std::string& phase,const fs::path& root){
    if(phase=="seed"){worker(phase,root);seedForeign();return;}if(phase=="later"){worker(phase,root);return;}
    TypeRegistry::instance().bootstrap();const State source=readState(root/"source.expected");const auto before=snapshot("base");expectedCells(before,earlyValues());const auto identity=g_engine.getTableSchema(DB,"base").physicalRelationId;const auto imageBefore=inventory(root/"image");
    if(phase=="active-high"){int i=0;while(TxnIdGenerator::instance().maxCommittedTxId()<=source.tx+3){check(i<128,"bounded genuine foreign advance");check(g_engine.insertRow(FOREIGN,"f",{{"id",std::to_string(100+i++)},{"n","1"},{"t","foreign-advance"}})==DBStatus::OK,"real higher-target committed allocation");}}
    if(phase=="active-low"||phase=="active-high"){
        ForeignHold hold(false);check(hold.waitReady(),"real active owner ready before restore");if(hold.error)std::rethrow_exception(hold.error);const bool higher=phase=="active-high";check(higher?hold.xid>source.tx:hold.xid<=source.tx,"real foreign xid versus genuine image floor");const auto counter=bytes(".txnid");std::atomic<bool> staged{false};const bool restored=g_engine.physicalRestore(DB,(root/"image").string(),[&](uint64_t){staged.store(true);return true;});check(staged.load(),"actual restore reached staged admission, not early fixture refusal");
        if(higher){check(restored,"foreign xid above image H permits real restore");checkSource(state(),source);}else{check(!restored,"existing foreign xid at/below image H strictly rejects");verifyUnchangedTarget(before,identity);check(bytes(".txnid")==counter,"rejected restore does not advance durable global counter");}
        hold.finish();hold.verify();std::cout<<"RESTORE_ADMISSION_ACTIVE phase="<<phase<<" xid="<<hold.xid<<" image_floor="<<source.tx<<" restored="<<restored<<" foreign_view_unchanged=1\n";
    }else{
        check(phase=="gap-low","only fixed concurrency worker mode");ForeignHold hold(true);std::thread restorer;std::exception_ptr restoreError;bool restored=false;std::atomic<bool> staged{false};
        struct JoinAll{ForeignHold& hold;std::thread& restorer;~JoinAll(){releaseGap();if(restorer.joinable())restorer.join();hold.finish();}}join{hold,restorer};
        {std::unique_lock<std::mutex> l(gap.mutex);check(gap.cv.wait_for(l,std::chrono::seconds(10),[]{return gap.allocated;}),"real nextTxId returned before active registration");check(gap.actualLock!=nullptr&&gap.xid>0&&gap.xid<=source.tx,"actual held shared mutex and genuinely conflicting allocated xid observed");}
        const auto counter=bytes(".txnid");restorer=std::thread([&]{try{watchRestoreExclusive=true;restored=g_engine.physicalRestore(DB,(root/"image").string(),[&](uint64_t){staged.store(true);return true;});watchRestoreExclusive=false;}catch(...){restoreError=std::current_exception();}{std::lock_guard<std::mutex> l(gap.mutex);gap.restoreDone=true;gap.cv.notify_all();}});
        bool blockedAtActualLock=false;{std::unique_lock<std::mutex> l(gap.mutex);check(gap.cv.wait_for(l,std::chrono::seconds(10),[]{return gap.writeAttempted||gap.restoreDone;}),"restore actual admission attempt or terminal observed");blockedAtActualLock=gap.writeAttempted&&gap.writeObservedBusy&&!gap.writeAcquired&&!gap.restoreDone&&!staged.load();gap.release=true;gap.cv.notify_all();}
        restorer.join();if(restoreError)std::rethrow_exception(restoreError);check(blockedAtActualLock,"actual matching admission mutex is read-held at restore exclusive boundary");check(staged.load()&&!restored,"after actual registration restore sees low active owner and rejects before publish");check(bytes(".txnid")==counter,"gap rejection preserves durable counter after real allocation");verifyUnchangedTarget(before,identity);hold.finish();hold.verify();check(hold.xid==gap.xid,"published real owner is exactly wrapped allocator result");std::cout<<"RESTORE_ADMISSION_GAP xid="<<hold.xid<<" image_floor="<<source.tx<<" actual_shared_mutex_busy=1 matching_exclusive_attempt=1 restored=0\n";
    }
    check(inventory(root/"image")==imageBefore,"whole source image immutable across concurrent admission");
}
void concurrentParent(const fs::path& exe){std::string pattern=(fs::temp_directory_path()/"dbms-restore-admission-XXXXXX").string();std::vector<char> value(pattern.begin(),pattern.end());value.push_back(0);const char* made=mkdtemp(value.data());check(made!=nullptr,"fresh admission root");const fs::path root=fs::canonical(made);std::cout<<"RESTORE_ADMISSION_ROOT "<<root<<'\n'<<std::flush;const auto early=root/"early";fs::create_directory(early);spawnWorker(exe,root,early,"seed");for(const auto& name:{"later","low","high","gap"})cloneClosed(early,root/name);spawnWorker(exe,root,root/"later","later");const auto image=inventory(root/"image");spawnWorker(exe,root,root/"low","active-low");spawnWorker(exe,root,root/"high","active-high");spawnWorker(exe,root,root/"gap","gap-low");check(inventory(root/"image")==image,"all concurrency cases retain original complete image");std::cout<<"RESTORE_ADMISSION_COMPLETE workers=5 real_foreign_owners=3 product_hooks=0\n";}
}
