std::string bytes(const fs::path& p) {
    std::ifstream in(p,std::ios::binary);check(bool(in),"read existing "+p.string());
    std::string s((std::istreambuf_iterator<char>(in)),{});check(!in.bad(),"complete read "+p.string());return s;
